def bsearch(arr, target):
    l = 0
    r = len(arr) - 1
    while l <= r:
        m = (l + r) // 2
        if arr[m] == target:
            return m
        elif arr[m] < target:
            l = m + 1
        else:
            r = m - 1
    return -1

# Binary search with recursive call
def search_rec(nums, k, lo, hi):
    if lo > hi:
        return -1
    mid = (lo + hi) // 2
    if nums[mid] == k:
        return mid
    if nums[mid] > k:
        return search_rec(nums, k, lo, mid - 1)
    return search_rec(nums, k, mid + 1, hi)

def find_target_index(sorted_sequence: list[int], target_value: int) -> int:
    """Finds the index of target_value in a sorted sequence using binary search."""
    low_boundary = 0
    high_boundary = len(sorted_sequence) - 1
    while low_boundary <= high_boundary:
        midpoint = (low_boundary + high_boundary) // 2
        current_value = sorted_sequence[midpoint]
        if current_value == target_value:
            return midpoint
        elif current_value < target_value:
            low_boundary = midpoint + 1
        else:
            high_boundary = midpoint - 1
    return -1

