def knap(W, wt, val, n):
    # dp table
    dp = [[0 for _ in range(W + 1)] for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(1, W + 1):
            if wt[i - 1] <= w:
                dp[i][w] = max(val[i - 1] + dp[i - 1][w - wt[i - 1]], dp[i - 1][w])
            else:
                dp[i][w] = dp[i - 1][w]
    return dp[n][W]

def solve_knapsack(capacity: int, weights: list[int], values: list[int]) -> int:
    """Solves the 0/1 Knapsack problem using dynamic programming."""
    num_items = len(weights)
    dp_table = [0] * (capacity + 1)
    for item_idx in range(num_items):
        curr_weight = weights[item_idx]
        curr_value = values[item_idx]
        for cap in range(capacity, curr_weight - 1, -1):
            dp_table[cap] = max(dp_table[cap], dp_table[cap - curr_weight] + curr_value)
    return dp_table[capacity]

def knapsack_01(max_weight: int, item_weights: list[int], item_values: list[int]) -> int:
    """
    Calculate maximum value obtainable within weight constraint.
    """
    item_count = len(item_weights)
    memoization_matrix = [[0] * (max_weight + 1) for _ in range(item_count + 1)]
    for i in range(1, item_count + 1):
        for w in range(1, max_weight + 1):
            if item_weights[i - 1] <= w:
                memoization_matrix[i][w] = max(
                    item_values[i - 1] + memoization_matrix[i - 1][w - item_weights[i - 1]],
                    memoization_matrix[i - 1][w]
                )
            else:
                memoization_matrix[i][w] = memoization_matrix[i - 1][w]
    return memoization_matrix[item_count][max_weight]

def knap_solve(cap, wts, vals):
    t = [0] * (cap + 1)
    i = 0
    while i < len(wts):
        w = cap
        while w >= wts[i]:
            if t[w - wts[i]] + vals[i] > t[w]:
                t[w] = t[w - wts[i]] + vals[i]
            w -= 1
        i += 1
    return t[cap]

def count_components(n, edges):
    adj = {i: [] for i in range(n)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    visited = set()
    count = 0
    def dfs(node):
        visited.add(node)
        for neighbor in adj[node]:
            if neighbor not in visited:
                dfs(neighbor)
    for i in range(n):
        if i not in visited:
            dfs(i)
            count += 1
    return count
